export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // Idempotency is scoped by (tenant, key). The lookup and the insert happen
    // synchronously before any await, so a single event-loop turn performs the
    // whole check-and-commit; concurrent callers therefore never race past the
    // guard and can never enqueue a duplicate debit.
    const existing = this.entries.find(e => e.tenant === tenant && e.key === key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    return receipt;
  }
}
EOF
cat > src/service.ts <<'EOF'
import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything before touching the ledger or the transport.
    if (typeof tenant !== 'string' || tenant.length === 0) throw new Error('invalid payment');
    if (typeof key !== 'string' || key.length === 0) throw new Error('invalid payment');
    if (!Number.isInteger(cents) || cents <= 0) throw new Error('invalid payment');
    if (!Number.isInteger(attempts) || attempts < 1 || attempts > 5) throw new Error('invalid payment');
    let lastError: unknown;
    for (let n = 0; n < attempts; n++) {
      try {
        // Ledger.apply is idempotent per (tenant, key): a retry re-debits
        // nothing and hands back the original receipt, so the transport is
        // acknowledged with the same receipt every time.
        const receipt = await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        lastError = error;
        if (!(error instanceof Transient)) throw error;
      }
    }
    // Retries exhausted: preserve the final thrown exception.
    throw lastError;
  }
}
EOF
cat > checks/idempotency.cjs <<'EOF'
const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Repeated equal amount returns the original receipt; no duplicate debit.
  const ledger = new Ledger();
  let acks = 0;
  const service = new PaymentService(ledger, {
    acknowledge: async r => { acks++; if (acks <= 2) throw new Transient('flaky'); },
  });
  const first = await service.pay('shop', 'sale', 123);
  const again = await service.pay('shop', 'sale', 123);
  assert.equal(again, first, 'must return the original receipt');
  assert.equal(ledger.entries.length, 1, 'no duplicate debit');

  // Concurrent equal calls commit exactly one debit and share one receipt.
  const ledger2 = new Ledger();
  const [a, b] = await Promise.all([
    ledger2.apply('shop', 'sale', 99),
    ledger2.apply('shop', 'sale', 99),
  ]);
  assert.equal(a, b);
  assert.equal(ledger2.entries.length, 1);

  // Key reuse with a different amount: key conflict, no extra debit.
  await assert.rejects(service.pay('shop', 'sale', 456), /key conflict/);
  assert.equal(ledger.entries.length, 1, 'conflict must not debit');
  assert.equal(acks, 2, 'conflict must not reach the transport');

  // Transient retried up to `attempts` total tries; same receipt each time.
  const seen = [];
  const ledger3 = new Ledger();
  let tries = 0;
  const flaky = new PaymentService(ledger3, {
    acknowledge: async r => { seen.push(r); tries++; if (tries < 3) throw new Transient('again'); },
  });
  await flaky.pay('t', 'k', 10, 3);
  assert.equal(tries, 3);
  assert.equal(ledger3.entries.length, 1);
  assert.ok(seen.every(r => r === seen[0]), 'same receipt forwarded each retry');

  // Exhausted retries preserve the final exception.
  const ledger4 = new Ledger();
  let n = 0;
  const dead = new PaymentService(ledger4, {
    acknowledge: async () => { n++; throw new Transient('boom-' + n); },
  });
  await assert.rejects(dead.pay('t', 'k', 5, 2), /boom-2/);
  assert.equal(n, 2);
  assert.equal(ledger4.entries.length, 1, 'exactly one debit despite failed acks');

  // Non-Transient errors are not retried.
  let once = 0;
  const strict = new PaymentService(new Ledger(), {
    acknowledge: async () => { once++; throw new Error('hard'); },
  });
  await assert.rejects(strict.pay('t', 'k', 5), /hard/);
  assert.equal(once, 1);

  // Validation before any ledger or transport action.
  const ledger5 = new Ledger();
  let touched = 0;
  const svc = new PaymentService(ledger5, { acknowledge: async () => { touched++; } });
  for (const args of [
    ['', 'k', 5, 3], ['t', '', 5, 3], ['t', 'k', 0, 3], ['t', 'k', 1.5, 3],
    ['t', 'k', 5, 0], ['t', 'k', 5, 6], ['t', 'k', 5, 2.5],
  ]) {
    await assert.rejects(svc.pay(...args), /invalid payment/);
  }
  assert.equal(ledger5.entries.length, 0);
  assert.equal(touched, 0);
}

module.exports = main();
EOF
